function isValidLocalVisit(value:unknown):value is LocalVisit {
 if(!value||typeof value!=='object')return false;
 const visit=value as Record<string,unknown>;
 if(typeof visit.verifiedAt!=='string'||!Number.isFinite(Date.parse(visit.verifiedAt)))return false;
 const timestamp=Date.parse(visit.verifiedAt);
 if(timestamp>Date.now()+5*60*1000)return false;
 return typeof visit.accuracy==='number'&&Number.isFinite(visit.accuracy)&&visit.accuracy>0&&visit.accuracy<=100;
}
function readIslandList(key:string):string[]{
 try{
  const parsed=JSON.parse(localStorage.getItem(key)||'[]');
  if(!Array.isArray(parsed))return [];
  return [...new Set(parsed.filter((name):name is string=>typeof name==='string'&&islands.some(island=>island.name===name)))];
 }catch{return []}
}
function readSavedPlaceMap():Record<string,string[]>{
 try{
  const parsed=JSON.parse(localStorage.getItem('graceon-passport-places-v1')||'{}');
  if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))return {};
  return Object.fromEntries(Object.entries(parsed).flatMap(([name,places])=>{
   const island=islands.find(item=>item.name===name);
   if(!island||!Array.isArray(places))return [];
   const validTitles=new Set(island.guide.sections.map(section=>section.title));
   const clean=[...new Set(places.filter((title):title is string=>typeof title==='string'&&validTitles.has(title)))];
   return clean.length?[[name,clean]]:[];
  }));
 }catch{return {}}
}
function persistLocalValue(key:string,value:unknown):void{
 try{localStorage.setItem(key,JSON.stringify(value))}catch{/* Storage may be disabled or full; keep the in-memory experience available. */}
}
function readLocalVisits():Record<string,LocalVisit>{
 try{
  const parsed=JSON.parse(localStorage.getItem('graceon-verified-checkins-v2')||'{}');
  if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))return {};
  return Object.fromEntries(Object.entries(parsed).filter(([name,visit])=>islands.some(island=>island.name===name)&&isValidLocalVisit(visit))) as Record<string,LocalVisit>;
 }catch{return {}}
}
